it('rejects a list_sessions frame whose limit is negative, fractional or not a number, or whose before cursor is malformed', () => {
  const validCursor = {updatedAt: '2026-01-01T00:00:00.000Z', sessionId: 's1'};
  const invalidLimits: unknown[] = ['ten', -1, 1.5];
  const invalidCursors: unknown[] = [
    'not-an-object',
    null,
    {...validCursor, sessionId: ''},
    {...validCursor, sessionId: 'x'.repeat(129)},
    {...validCursor, sessionId: 42},
    {...validCursor, updatedAt: 'not-a-date'},
    {...validCursor, updatedAt: true},
    {...validCursor, updatedAt: Number.NaN},
  ];
  const rejected = [
    ...invalidLimits.map(limit => ({type: 'list_sessions', limit})),
    ...invalidCursors.map(before => ({type: 'list_sessions', before})),
  ];

  const accepted = rejected.filter(frame => validateMessage(frame).valid);

  expect(accepted).toEqual([]);
});

